<?php
/**
 * Template personalizado para la tienda SDexpress en Dokan
 * Reemplaza completamente el diseño estándar de Dokan para esta tienda específica
 *
 * @package Tema IslaBeya
 */

if ( ! defined( 'ABSPATH' ) ) {
    exit; // Exit if accessed directly
}

$store_user   = dokan()->vendor->get( get_query_var( 'author' ) );
$store_info   = $store_user->get_shop_info();
$map_location = $store_user->get_location();

// Obtener información del vendedor para la sección específica
$store_name = ! empty( $store_info['store_name'] ) ? $store_info['store_name'] : get_the_author_meta( 'display_name', $store_user->get_id() );
$store_address = ! empty( $store_info['address']['street_1'] ) ? $store_info['address']['street_1'] : '';
if ( ! empty( $store_info['address']['city'] ) ) {
    $store_address .= ', ' . $store_info['address']['city'];
}
if ( ! empty( $store_info['address']['state'] ) ) {
    $store_address .= ', ' . $store_info['address']['state'];
}
$store_phone = ! empty( $store_info['phone'] ) ? $store_info['phone'] : '';
$store_email = ! empty( $store_info['email'] ) ? $store_info['email'] : get_the_author_meta( 'user_email', $store_user->get_id() );

// Obtener productos de la tienda
$store_user_id = method_exists( $store_user, 'get_id' ) ? $store_user->get_id() : 0;

// Límite de productos visibles por sección (configurable)
$products_limit = 20;

// Slugs de categorías (reemplazar según sea necesario)
$category_slugs = [
    'motos' => 'motos',
    'kits-solares' => 'kits-solares',
    'contenedor' => 'contenedor',
    'baterias' => 'baterias',
    'abastecimientos-basicos' => 'abastecimientos-basicos',
];

// Query para productos por categorías
$products_by_category = [];
foreach ( $category_slugs as $key => $slug ) {
    $products_by_category[ $key ] = new WP_Query([
        'post_type'      => 'product',
        'post_status'    => 'publish',
        'ignore_sticky_posts' => 1,
        'author'         => $store_user_id,
        'tax_query'      => [
            [
                'taxonomy' => 'product_cat',
                'field'    => 'slug',
                'terms'    => $slug,
            ],
        ],
        'posts_per_page' => -1, // Todos los productos de la categoría
        'no_found_rows'  => true,
    ]);
}

// Query para motos destacadas
$featured_motos = new WP_Query([
    'post_type'      => 'product',
    'post_status'    => 'publish',
    'ignore_sticky_posts' => 1,
    'author'         => $store_user_id,
    'tax_query'      => [
        'relation' => 'AND',
        [
            'taxonomy' => 'product_cat',
            'field'    => 'slug',
            'terms'    => 'motos',
        ],
        [
            'taxonomy' => 'product_visibility',
            'field'    => 'slug',
            'terms'    => [ 'featured' ],
        ],
    ],
    'no_found_rows'  => true,
]);

// Obtener IDs de motos destacadas
$featured_motos_ids = array_map( 'intval', wp_list_pluck( $featured_motos->posts, 'ID' ) );

// Query para motos no destacadas
$non_featured_motos = new WP_Query([
    'post_type'      => 'product',
    'post_status'    => 'publish',
    'ignore_sticky_posts' => 1,
    'author'         => $store_user_id,
    'tax_query'      => [
        'relation' => 'AND',
        [
            'taxonomy' => 'product_cat',
            'field'    => 'slug',
            'terms'    => 'motos',
        ],
    ],
    'post__not_in'   => $featured_motos_ids,
    'posts_per_page' => -1, // Todos los productos de motos no destacadas
    'no_found_rows'  => true,
]);

// Agregar clase al body para estilos específicos
add_filter( 'body_class', function( $classes ) {
    $classes[] = 'sd-express-store';
    return $classes;
});
