    <script>
    document.addEventListener('DOMContentLoaded', function() {
        var loadMoreButtons = document.querySelectorAll('.sd-express-load-more-btn');
        
        loadMoreButtons.forEach(function(button) {
            button.addEventListener('click', function(e) {
                e.preventDefault();
                
                var section = this.getAttribute('data-section');
                var limit = parseInt(this.getAttribute('data-limit'));
                var total = parseInt(this.getAttribute('data-total'));
                
                var productGrid = this.closest('.sd-express-product-grid');
                var hiddenProducts = productGrid.querySelectorAll('.sd-express-product-hidden');
                var visibleCount = productGrid.querySelectorAll('.sd-express-product-item:not(.sd-express-product-hidden)').length;
                
                var nextLimit = visibleCount + limit;
                var productsToShow = 0;
                
                hiddenProducts.forEach(function(product, index) {
                    if (productsToShow < limit && (visibleCount + index) < total) {
                        product.style.display = 'block';
                        product.classList.remove('sd-express-product-hidden');
                        productsToShow++;
                    }
                });
                
                var newVisibleCount = productGrid.querySelectorAll('.sd-express-product-item:not(.sd-express-product-hidden)').length;
                
                if (newVisibleCount >= total) {
                    this.style.display = 'none';
                }
            });
        });
    });
    </script>
    
